<script lang="ts">
  import {untrack} from 'svelte';
  import ProfilePortEditor from './ProfilePortEditor.svelte';
  import ProfileValueEditor from './ProfileValueEditor.svelte';
  import {processingNodeError,processingSummary} from './profile-processing';
  import {portContractLabel} from './profile-canvas';
  import type{DeepReadonly,ProfileActionParameter,ProfileOperation,ProfilePort,ProfilePortContract,ProfileProcessingNode,ProfileScalarSchema,ProfileValue}from'./profiles';
  let {node,change,actions=[]}:{node:DeepReadonly<ProfileProcessingNode>;change:(node:ProfileProcessingNode)=>void;actions?:{label:string;contract:DeepReadonly<ProfilePortContract>}[]}=$props();
  const copy=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
  let draft=$state<ProfileProcessingNode>(copy(untrack(()=>node)) as ProfileProcessingNode),signature=$state(JSON.stringify(untrack(()=>node))),actionIndex=$state('');
  const error=$derived(processingNodeError(draft));
  const packed=$derived(draft.operation.kind==='action-pack'||draft.operation.kind==='set-on-change');
  const declaringQuantity=$derived(draft.operation.kind==='declare-quantity');
  const firstOutput=$derived(draft.outputs[0]?.contract);
  const outputSchema=$derived(firstOutput&&'schema'in firstOutput?firstOutput.schema:null);
  $effect(()=>{const next=JSON.stringify(node);if(next!==signature){signature=next;draft=copy(node) as ProfileProcessingNode;}});
  const heading=(key:string)=>key.replace(/([A-Z])/g,' $1').replace(/^./,letter=>letter.toUpperCase());
  function field(key:string,value:unknown){const outputs=draft.operation.kind==='declare-quantity'&&key==='unit'&&typeof value==='string'?draft.outputs.map(port=>'schema'in port.contract&&(port.contract.schema.type==='integer'||port.contract.schema.type==='number')?{...port,contract:{...port.contract,schema:{...port.contract.schema,unit:value}}}:port):draft.outputs;draft={...draft,operation:{...draft.operation,[key]:value} as ProfileOperation,outputs};}
  function save(){if(!processingNodeError(draft))change(copy(draft));}
  function ruleField(key:string,value:unknown){if(draft.operation.kind==='builtin')draft={...draft,operation:{...draft.operation,rule:{...draft.operation.rule,[key]:value} as typeof draft.operation.rule}};}
  function editPort(direction:'input'|'output',index:number,port:ProfilePort){const key=direction==='input'?'inputs':'outputs';draft={...draft,[key]:draft[key].map((current,i)=>i===index?port:current)};}
  function addPort(direction:'input'|'output',contract:ProfilePortContract={delivery:'state',schema:{type:'boolean'},freshnessMs:1000,fallback:null}){const used=new Set([...draft.inputs,...draft.outputs].map(port=>port.id));let n=1;while(used.has(`${direction}-${n}`))n++;const port:ProfilePort={id:`${direction}-${n}`,name:`${direction} ${n}`,direction,contract};const key=direction==='input'?'inputs':'outputs';draft={...draft,[key]:[...draft[key],port]};}
  function invocation(){const action=actions[Number(actionIndex)]?.contract;if(action?.delivery!=='action')return;addPort('output',{delivery:'invocation',parameters:copy(action.parameters) as ProfileActionParameter[],semantics:action.semantics});}
  function addParameter(){if(draft.operation.kind!=='script')return;let n=1;while(Object.hasOwn(draft.operation.parameters,`parameter-${n}`))n++;field('parameters',{...draft.operation.parameters,[`parameter-${n}`]:false});}
  function parameter(id:string,value:Exclude<ProfileValue,null>){if(draft.operation.kind==='script')field('parameters',{...draft.operation.parameters,[id]:value});}
  function parameterName(old:string,id:string){if(draft.operation.kind!=='script')return;field('parameters',Object.fromEntries(Object.entries(draft.operation.parameters).map(([key,value])=>[key===old?id:key,value])));}
  function priority(index:number,delta:number){if(draft.operation.kind!=='priority')return;const order=[...draft.operation.order],other=index+delta;if(other<0||other>=order.length)return;[order[index],order[other]]=[order[other],order[index]];field('order',order);}
  function addBuiltinCurvePoint(){if(draft.operation.kind!=='builtin'||draft.operation.rule.kind!=='axis')return;const contract=draft.inputs[0]?.contract,schema=contract&&'schema'in contract?contract.schema:null;if(!schema||schema.type!=='integer'&&schema.type!=='number')return;const points=[...draft.operation.rule.curve];if(points.length<2){ruleField('curve',[{input:schema.min,output:schema.min},{input:schema.max,output:schema.max}]);return;}let index=0;for(let i=1;i<points.length-1;i++)if(points[i+1].input-points[i].input>points[index+1].input-points[index].input)index=i;points.splice(index+1,0,{input:Math.floor((points[index].input+points[index+1].input)/2),output:Math.floor((points[index].output+points[index+1].output)/2)});ruleField('curve',points);}
</script>
<section class="processing-editor" aria-label="Visible transformation editor">
  <h4>Visible transformation</h4><p class="summary">{processingSummary(draft)}</p>
  <label>Block label<input value={draft.name} maxlength="80" oninput={event=>draft={...draft,name:event.currentTarget.value}}/></label>
  <p class="hint">Operation: <code>{draft.operation.kind}</code>. Parameters belong to this drawn block.</p>
  {#if draft.operation.kind==='declare-quantity'}
    <label>Quantity definition<input value={draft.operation.quantity} maxlength="128" oninput={event=>field('quantity',event.currentTarget.value)}/></label>
    <label>Declared unit<input value={draft.operation.unit} maxlength="128" oninput={event=>field('unit',event.currentTarget.value)}/></label>
    <p class="hint">Enter the provider's documented quantity definition and unit, including the altitude reference when relevant. This is the author's interpretation: values, numeric type and range stay unchanged. Calibrate raw encoding first with Scale and offset or Map numeric range, then Convert units after this declaration. Quantity and unit must be nonempty, trimmed and at most 128 UTF-8 bytes each. Source quality and provenance still come from the provider.</p>
  {:else if draft.operation.kind==='constant'&&outputSchema}<ProfileValueEditor schema={outputSchema} value={draft.operation.value} label="Constant" change={value=>{if(value!==null)field('value',value);}}/>
  {:else if draft.operation.kind==='select'&&outputSchema}<ProfileValueEditor schema={outputSchema} value={draft.operation.whenTrue} label="When true" change={value=>{if(value!==null)field('whenTrue',value);}}/><ProfileValueEditor schema={outputSchema} value={draft.operation.whenFalse} label="When false" change={value=>{if(value!==null)field('whenFalse',value);}}/>
  {:else if draft.operation.kind==='fallback'&&outputSchema}{#each ['unknown','stale','unavailable'] as key}<ProfileValueEditor schema={outputSchema} value={draft.operation[key as 'unknown'|'stale'|'unavailable']} label={heading(key)} change={value=>{if(value!==null)field(key,value);}}/>{/each}
  {:else if draft.operation.kind==='script'}
    <label>Typed Rhai source<textarea rows="12" value={draft.operation.source} oninput={event=>field('source',event.currentTarget.value)} spellcheck="false"></textarea></label>
    <p class="hint">Inputs are <code>ctx.inputs["port-id"]</code> typed envelopes. Return <code>transaction(ctx.state, #&#123;out:scalar(value)&#125;, [])</code>. Unknown, stale and unavailable remain distinct. Typed timers use <code>after</code> outputs; they do not call on_timer. Native compilation and worker diagnostics remain authoritative.</p>
    <details><summary>Typed script parameters ({Object.keys(draft.operation.parameters).length})</summary>{#each Object.entries(draft.operation.parameters) as [key,value]}<fieldset><label>Parameter name<input value={key} oninput={event=>parameterName(key,event.currentTarget.value)}/></label><label>Type<select value={typeof value} onchange={event=>parameter(key,event.currentTarget.value==='boolean'?false:event.currentTarget.value==='number'?0:'')}><option value="boolean">Boolean</option><option value="number">Number</option><option value="string">Text</option></select></label><ProfileValueEditor schema={typeof value==='boolean'?{type:'boolean'}:typeof value==='number'?{type:'number',min:-Number.MAX_SAFE_INTEGER,max:Number.MAX_SAFE_INTEGER,unit:null}:{type:'text',maxBytes:4096,encoding:'utf8'}} {value} label="Parameter value" change={next=>{if(next!==null)parameter(key,next);}}/><button class="text-button" onclick={()=>{if(draft.operation.kind==='script')field('parameters',Object.fromEntries(Object.entries(draft.operation.parameters).filter(([id])=>id!==key)));}}>Remove parameter</button></fieldset>{/each}<button class="secondary-button" disabled={Object.keys(draft.operation.parameters).length>=64} onclick={addParameter}>Add parameter</button></details>
  {:else if draft.operation.kind==='priority'}<ol class="priority">{#each draft.operation.order as id,index (id)}<li><code>{id}</code><button aria-label={`Raise ${id} priority`} disabled={index===0} onclick={()=>priority(index,-1)}>↑</button><button aria-label={`Lower ${id} priority`} disabled={index===draft.inputs.length-1} onclick={()=>priority(index,1)}>↓</button></li>{/each}</ol>
  {:else if packed}<p class="hint">Every argument below is a named state input. Route a source or a visible Constant node to each argument. {draft.operation.kind==='action-pack'?'The separate event input triggers one complete ordered invocation.':'A complete setter invocation is emitted only on an argument change.'}</p>
  {:else}
    {#each Object.entries(draft.operation).filter(([key])=>!['kind','rule','inputs','points'].includes(key)) as [key,value]}
      {#if typeof value==='number'}<label>{heading(key)}<input type="number" value={value} step="any" oninput={event=>field(key,Number(event.currentTarget.value))}/></label>
      {:else if typeof value==='string'}<label>{heading(key)}{#if ['rounding','comparison','edge','overflow'].includes(key)}<select value={value} onchange={event=>field(key,event.currentTarget.value)}>{#each key==='rounding'?['none','nearest','floor','ceil','truncate']:key==='comparison'?['greater','greater-equal','less','less-equal','equal','not-equal']:key==='edge'?['rising','falling','change']:['reject','truncate'] as option}<option value={option}>{option}</option>{/each}</select>{:else}<input value={value} oninput={event=>field(key,event.currentTarget.value)}/>{/if}</label>{/if}
    {/each}
    {#if draft.operation.kind==='curve'}<h5>Ordered curve points</h5>{#each draft.operation.points as point,index}<div class="pair"><label>Input {index+1}<input type="number" step="any" value={point.input} oninput={event=>{if(draft.operation.kind==='curve')field('points',draft.operation.points.map((p,i)=>i===index?{...p,input:Number(event.currentTarget.value)}:p));}}/></label><label>Output {index+1}<input type="number" step="any" value={point.output} oninput={event=>{if(draft.operation.kind==='curve')field('points',draft.operation.points.map((p,i)=>i===index?{...p,output:Number(event.currentTarget.value)}:p));}}/></label><button class="text-button" onclick={()=>{if(draft.operation.kind==='curve')field('points',draft.operation.points.filter((_,i)=>i!==index));}}>Remove point</button></div>{/each}<button class="secondary-button" disabled={draft.operation.points.length>=32} onclick={()=>{if(draft.operation.kind==='curve'){const last=draft.operation.points.at(-1)!;field('points',[...draft.operation.points,{input:last.input+1,output:last.output}]);}}}>Add curve point</button>{/if}
    {#if draft.operation.kind==='builtin'}<h5>{draft.operation.rule.kind} parameters</h5>{#each Object.entries(draft.operation.rule).filter(([key])=>!['kind','curve','steps'].includes(key)) as [key,value]}{#if typeof value==='boolean'}<label class="check"><input type="checkbox" checked={value} onchange={event=>ruleField(key,event.currentTarget.checked)}/>{heading(key)}</label>{:else if typeof value==='number'}<label>{heading(key)} (µs for timing)<input type="number" value={value} oninput={event=>ruleField(key,Number(event.currentTarget.value))}/></label>{:else if typeof value==='string'}<label>{heading(key)}<input value={value} oninput={event=>ruleField(key,event.currentTarget.value)}/></label>{/if}{/each}
      {#if draft.operation.rule.kind==='axis'}<h5>Declared native-axis curve</h5>{#each draft.operation.rule.curve as point,index}<div class="pair"><label>Input {index+1}<input type="number" value={point.input} oninput={event=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='axis')ruleField('curve',draft.operation.rule.curve.map((p,i)=>i===index?{...p,input:Number(event.currentTarget.value)}:p));}}/></label><label>Output {index+1}<input type="number" value={point.output} oninput={event=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='axis')ruleField('curve',draft.operation.rule.curve.map((p,i)=>i===index?{...p,output:Number(event.currentTarget.value)}:p));}}/></label><button class="text-button" onclick={()=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='axis')ruleField('curve',draft.operation.rule.curve.filter((_,i)=>i!==index));}}>Remove curve point</button></div>{/each}<button class="secondary-button" disabled={draft.operation.rule.curve.length>=32} onclick={addBuiltinCurvePoint}>Add native-axis curve point</button>{/if}
      {#if draft.operation.rule.kind==='macro'}{#each draft.operation.rule.steps as step,index}<div class="pair"><label>After (µs)<input type="number" min="0" max="60000000" value={step.afterUs} oninput={event=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='macro')ruleField('steps',draft.operation.rule.steps.map((p,i)=>i===index?{...p,afterUs:Number(event.currentTarget.value)}:p));}}/></label><label class="check"><input type="checkbox" checked={step.pressed} onchange={event=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='macro')ruleField('steps',draft.operation.rule.steps.map((p,i)=>i===index?{...p,pressed:event.currentTarget.checked}:p));}}/>Pressed</label><button class="text-button" onclick={()=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='macro')ruleField('steps',draft.operation.rule.steps.filter((_,i)=>i!==index));}}>Remove step</button></div>{/each}<button class="secondary-button" disabled={draft.operation.rule.steps.length>=16} onclick={()=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='macro')ruleField('steps',[...draft.operation.rule.steps,{afterUs:(draft.operation.rule.steps.at(-1)?.afterUs??0)+100000,pressed:false}]);}}>Add macro step</button>{/if}
    {/if}
  {/if}
  <details><summary>Declared ports · {draft.inputs.length} inputs / {draft.outputs.length} outputs</summary>
    {#each draft.inputs as port,index (index)}{#if packed||declaringQuantity}<div class="argument"><strong>{port.name}</strong><code>{port.id}</code><p>{portContractLabel(port.contract)}</p></div>{:else}<ProfilePortEditor {port} change={next=>editPort('input',index,next)}/><button class="text-button" onclick={()=>draft={...draft,inputs:draft.inputs.filter((_,i)=>i!==index)}}>Remove input {port.id}</button>{/if}{/each}
    {#each draft.outputs as port,index (index)}{#if declaringQuantity}<div class="argument"><strong>{port.name}</strong><code>{port.id}</code><p>{portContractLabel(port.contract)}</p></div>{:else}<ProfilePortEditor {port} identityEditable={!packed} change={next=>editPort('output',index,next)}/>{#if !packed}<button class="text-button" onclick={()=>draft={...draft,outputs:draft.outputs.filter((_,i)=>i!==index)}}>Remove output {port.id}</button>{/if}{/if}{/each}
    {#if !packed&&!declaringQuantity}<div class="actions"><button class="secondary-button" disabled={draft.inputs.length>=(draft.operation.kind==='script'?32:128)} onclick={()=>addPort('input')}>Add input port</button><button class="secondary-button" disabled={draft.outputs.length>=16} onclick={()=>addPort('output')}>Add output port</button></div>{/if}
    {#if draft.operation.kind==='script'&&actions.length}<label>Invocation output target<select bind:value={actionIndex}><option value="">Choose an advertised action</option>{#each actions as action,index}<option value={index}>{action.label}</option>{/each}</select></label><button class="secondary-button" disabled={actionIndex===''||draft.outputs.length>=16} onclick={invocation}>Declare invocation output</button>{/if}
  </details>
  {#if error}<p class="error" role="status">{error}</p>{/if}
  <button class="primary-button" disabled={!!error} onclick={save}>Update visible node</button>
</section>
<style>
  .processing-editor{border-top:1px solid var(--line);padding-top:15px;margin-top:16px;min-width:0}h4{font-size:12px;color:var(--soft)}h5{font-size:10px;margin:14px 0;color:var(--soft)}.summary,.hint,.argument p{font-size:10px;color:var(--muted);line-height:1.75;margin:10px 0;overflow-wrap:anywhere}.processing-editor label{display:grid;gap:6px;font-size:9px;color:var(--muted);margin:10px 0}.processing-editor input:not([type="checkbox"]),select,textarea{width:100%;min-width:0;box-sizing:border-box;background:var(--input-bg);border:1px solid var(--line);border-radius:5px;padding:8px;color:var(--text);font-size:10px}textarea{font-family:monospace;line-height:1.7}.check{display:flex!important;align-items:center;gap:7px!important}.pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}.pair button{grid-column:1/-1}.processing-editor button{font-size:10px}.actions{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.processing-editor details{margin:15px 0}.processing-editor summary{font-size:10px;cursor:pointer;color:var(--soft)}.processing-editor fieldset{border:1px solid var(--line);padding:10px;margin:12px 0;min-width:0}.error{font-size:10px;color:#d3a078;line-height:1.8}.priority{padding-left:16px;font-size:10px}.priority li{padding:7px 0}.priority button{margin-left:8px;padding:4px;background:var(--surface-raised);color:var(--soft)}.argument{border-bottom:1px solid var(--line);padding:12px 0}.argument strong,.argument code{display:block;font-size:10px}.argument code{font-size:9px;color:var(--muted);margin-top:5px}
</style>
